import os
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('hotel-payments')
stripe.api_key = os.environ['STRIPE_SECRET_KEY']
_ZERO_DECIMAL = {'jpy', 'krw', 'vnd', 'clp'}
_CANCELABLE = {'requires_payment_method', 'requires_confirmation', 'requires_action', 'requires_capture'}

def _to_minor(amt, cur):
    if cur in _ZERO_DECIMAL:
        return int(round(amt))
    return int(round(amt * 100))

@mcp.tool()
def charge_hotel_deposit(customer_id: str, payment_method_id: str, reservation_ref: str, nightly_rate: float, nights: int, deposit_pct: float=20.0, currency: str='usd') -> dict:
    cur = currency.lower().strip()
    if len(cur) != 3:
        return {'ok': False, 'error': 'currency must be a 3-letter ISO code'}
    if nights < 1:
        return {'ok': False, 'error': 'nights must be at least 1'}
    if nightly_rate <= 0:
        return {'ok': False, 'error': 'nightly_rate must be positive'}
    if not 1 <= deposit_pct <= 100:
        return {'ok': False, 'error': 'deposit_pct must be between 1 and 100'}
    tot = nightly_rate * nights
    dep = tot * deposit_pct / 100.0
    amt = _to_minor(dep, cur)
    if amt < 50 and cur not in _ZERO_DECIMAL:
        return {'ok': False, 'error': 'deposit below minimum chargeable amount'}
    # Cancel stale, incomplete deposit attempts for this reservation before charging
    canceled = []
    try:
        prior = stripe.PaymentIntent.search(query=f"customer:'{customer_id}' AND metadata['reservation_ref']:'{reservation_ref}'")
        for old in prior.auto_paging_iter():
            if old.status in _CANCELABLE:
                stripe.PaymentIntent.cancel(old.id, cancellation_reason='duplicate')
                canceled.append(old.id)
    except stripe.error.StripeError as e:
        return {'ok': False, 'error': f'failed to cancel prior attempts: {e}'}
    try:
        pi = stripe.PaymentIntent.create(amount=amt, currency=cur, customer=customer_id, payment_method=payment_method_id, off_session=True, confirm=True, description=f'Hotel deposit {reservation_ref}', metadata={'reservation_ref': reservation_ref, 'nights': str(nights)}, idempotency_key=f'hotel-dep-{reservation_ref}')
    except stripe.error.CardError as e:
        return {'ok': False, 'error': e.user_message or 'card declined'}
    except stripe.error.StripeError as e:
        return {'ok': False, 'error': str(e)}
    return {'ok': pi.status == 'succeeded', 'payment_intent_id': pi.id, 'status': pi.status, 'amount_charged': round(dep, 2), 'currency': cur, 'reservation_ref': reservation_ref, 'canceled_payment_intents': canceled}
